def smallestDistancePair(nums: list[int], k: int) -> int:
    nums.sort()
    lo, hi = 0, nums[-1] - nums[0]
    def count_pairs(diff):
        count = 0
        left = 0
        for right in range(len(nums)):
            while nums[right] - nums[left] > diff:
                left += 1
            count += right - left
        return count
    while lo < hi:
        mid = (lo + hi) // 2
        if count_pairs(mid) < k:
            lo = mid + 1
        else:
            hi = mid
    return lo

